#include <bits/stdc++.h>

using namespace std;

using int64 = long long;

constexpr int64 MOD = 1000000007;

class FieldElement {
 private:
  int64 val;
 public:
  FieldElement(int64 v = 0) : val(v % MOD) {
    if (val < 0) val += MOD;
    if (val >= MOD) { cerr << "FieldElement overflow!" << endl; exit(1); }
  }
  int64 get() const { return val; }
  FieldElement operator+(const FieldElement& o) const {
    return FieldElement((val + o.val) % MOD);
  }
  FieldElement operator-(const FieldElement& o) const {
    return FieldElement((val - o.val + MOD) % MOD);
  }
  FieldElement operator*(const FieldElement& o) const {
    return FieldElement((val * o.val) % MOD);
  }
  FieldElement operator/(const FieldElement& o) const {
    return (*this) * o.inverse();
  }
  FieldElement& operator+=(const FieldElement& o) {
    val = (val + o.val) % MOD;
    return *this;
  }
  FieldElement& operator-=(const FieldElement& o) {
    val = (val - o.val + MOD) % MOD;
    return *this;
  }
  FieldElement& operator*=(const FieldElement& o) {
    val = (val * o.val) % MOD;
    return *this;
  }
  FieldElement& operator/=(const FieldElement& o) {
    return (*this) *= o.inverse();
  }
  FieldElement inverse() const {
    int64 exp = MOD - 2;
    int64 base = val;
    int64 res = 1;
    while (exp) {
      if (exp & 1) res = (res * base) % MOD;
      base = (base * base) % MOD;
      exp >>= 1;
    }
    return FieldElement(res);
  }
};

template<typename T>
vector<vector<T>> matmul(const vector<vector<T>>& A, const vector<vector<T>>& B) {
  int rowsA = A.size();
  int colsA = A[0].size();
  int rowsB = B.size();
  int colsB = B[0].size();
  if (colsA != rowsB) {
    cerr << "Matrix multiplication dimension mismatch!" << endl;
    exit(1);
  }
  vector<vector<T>> result(rowsA, vector<T>(colsB, T(0)));
  for (int i = 0; i < rowsA; ++i) {
    for (int j = 0; j < colsB; ++j) {
      for (int k = 0; k < colsA; ++k) {
        result[i][j] = result[i][j] + A[i][k] * B[k][j];
      }
    }
  }
  return result;
}

template<typename T>
vector<T> matvecmul(const vector<vector<T>>& A, const vector<T>& v) {
  int rows = A.size();
  int cols = A[0].size();
  if (v.size() != cols) {
    cerr << "Matrix-vector dimension mismatch!" << endl;
    exit(1);
  }
  vector<T> result(rows, T(0));
  for (int i = 0; i < rows; ++i) {
    for (int j = 0; j < cols; ++j) {
      result[i] = result[i] + A[i][j] * v[j];
    }
  }
  return result;
}

template<typename T>
vector<vector<T>> make2D(int r, int c, const T& val = T()) {
  return vector<vector<T>>(r, vector<T>(c, val));
}

template<typename T>
vector<vector<vector<T>>> make3D(int d1, int d2, int d3, const T& val = T()) {
  return vector<vector<vector<T>>>(d1, vector<vector<T>>(d2, vector<T>(d3, val)));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int64 n;
  int d;
  cin >> n >> d;

  auto shifts = make3D<FieldElement>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k) {
    for (int i = 0; i < d; ++i) {
      shifts[k][i][(i + k) % d] = FieldElement(1);
    }
    shifts[k][d][d] = FieldElement(1);
  }

  auto units = make3D<FieldElement>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k) {
    for (int i = 0; i < d + 1; ++i) {
      units[k][i][i] = FieldElement(1);
    }
    for (int i = 0; i < d + 1; ++i) {
      units[k][k][i] = FieldElement(1);
    }
  }

  auto I = make2D<FieldElement>(d + 1, d + 1);
  for (int i = 0; i < d + 1; ++i) {
    I[i][i] = FieldElement(1);
  }

  unordered_map<int64, vector<vector<FieldElement>>> memo;

  function<vector<vector<FieldElement>>(int64)> buildMatrix = [&](int64 p) {
    if (memo.count(p)) return memo[p];
    if (p <= d) {
      auto M = I;
      for (int k = 0; k < p; ++k) {
        M = matmul(units[k], M);
      }
      return M;
    }
    int64 block = d;
    while ((p + block - 1) / block > d) block *= d;
    auto child = buildMatrix(block);
    auto M = child;
    int64 rem = p - block;
    for (int k = 1; k < d; ++k) {
      if (rem >= block) {
        M = matmul(matmul(matmul(shifts[d - k], child), shifts[k]), M);
        rem -= block;
      } else if (rem > 0) {
        M = matmul(matmul(matmul(shifts[d - k], buildMatrix(rem)), shifts[k]), M);
        rem = 0;
      } else {
        break;
      }
    }
    return memo[p] = M;
  };

  auto M = buildMatrix(n);
  vector<FieldElement> base(d + 1);
  base[d] = FieldElement(1);
  auto resVec = matvecmul(M, base);
  FieldElement total;
  for (const auto& x : resVec) total += x;
  cout << total.get() << '\n';
}
